from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
for ws in wb.worksheets:
    print('Sheet', ws.title, 'max', ws.max_row, ws.max_column)
    for r in range(1, ws.max_row+1):
        hits=[]
        for c in range(1, ws.max_column+1):
            v=ws.cell(r,c).value
            if v in [2018,2019,2020,2021,2022] or str(v) in ['2018','2019','2020','2021','2022']:
                hits.append(f'{get_column_letter(c)}{r}={v!r}')
        if hits:
            print(' ', ' | '.join(hits))
